"use client";
import{Fragment,useEffect,useMemo,useState}from"react";
import{session,login,getAccounts,getEmployees,getDepartments,getSystems,getReviews,createItem,updateItem,deleteItem,getCurrentUser,getPortalUsers,getRoles,createPortalUser,updatePortalUser,deletePortalUser,getGovernanceState}from"../lib/directus";
import GitHubSync from "./GitHubSync";
import{GovernanceWorkspace,PermissionPage}from"./GovernanceViews";
import{ConnectorOps,DeviceOps}from"./OperationsViews";
function portalRoleName(me:any){if(session.username()==="administrator")return"Administrator";const tokenRole=session.claims()?.role;const id=tokenRole||(typeof me?.role==="string"?me.role:me?.role?.id);const directName=typeof me?.role==="object"?me.role?.name:"";const map:any={"a1000000-0000-4000-8000-000000000001":"账号管理员","a1000000-0000-4000-8000-000000000002":"审计人员","a1000000-0000-4000-8000-000000000003":"只读用户","3c558943-486a-4fc7-b89e-d61a1f62e88c":"Administrator","c704f3d9-9076-4fea-95d3-d356d7d130f8":"Administrator"};return directName||map[id]||"只读用户"}
const NAV=["治理工作台","账号台账","系统管理","设备资产","员工管理","部门管理","同步中心","用户与权限","权限说明"];
const ROLE_NAV:any={"Administrator":NAV,"IT账号管理员":NAV.filter(x=>x!=="用户与权限"),"应用负责人":["治理工作台","账号台账","权限说明"],"审计人员":["治理工作台","账号台账","设备资产","权限说明"],"只读用户":["治理工作台","账号台账","权限说明"]};
const NAV_ICONS:Record<string,string>={"治理工作台":"⌂","账号台账":"◎","系统管理":"◇","设备资产":"▣","员工管理":"♙","部门管理":"▤","同步中心":"↻","用户与权限":"⚿"};
export default function Home(){
 const[ready,setReady]=useState(false),[auth,setAuth]=useState(false),[tab,setTab]=useState("治理工作台"),[data,setData]=useState<any>({accounts:[],employees:[],departments:[],systems:[],reviews:[],licenses:[],me:null,users:[],roles:[],governance:{requests:[],risks:[],connectors:[],syncRuns:[],devices:[],audits:[]}}),[modal,setModal]=useState(""),[selected,setSelected]=useState<any>(null),[toast,setToast]=useState("");
 async function load(){try{const me=await getCurrentUser();const[a0,e0,d,s,r0,g]=await Promise.all([getAccounts(),getEmployees(),getDepartments(),getSystems(),getReviews(),getGovernanceState()]);const e=e0.map((x:any)=>({...x,department:x.department?(d.find((v:any)=>String(v.id)===String(typeof x.department==="object"?x.department.id:x.department))||x.department):null}));const a=a0.map((x:any)=>{const employeeId=typeof x.employee==="object"?x.employee?.id:x.employee,systemId=typeof x.system==="object"?x.system?.id:x.system;return{...x,employee:employeeId?(e.find((v:any)=>String(v.id)===String(employeeId))||x.employee):null,system:systemId?(s.find((v:any)=>String(v.id)===String(systemId))||x.system):null}}),r=r0.map((x:any)=>({...x,account:typeof x.account==="string"?a.find((v:any)=>String(v.id)===String(x.account))||null:x.account}));let users:any[]=[],roles:any[]=[];if(portalRoleName(me)==="Administrator"){[users,roles]=await Promise.all([getPortalUsers(),getRoles()])}setData({accounts:a,employees:e,departments:d,systems:s,reviews:r,licenses:[],me,users,roles,governance:g});setAuth(true)}catch(e:any){if(session.has()){setAuth(true);note(e?.message||"数据刷新失败，请稍后重试")}else setAuth(false)}finally{setReady(true)}}
 useEffect(()=>{session.resume();if(session.has())load();else setReady(true)},[]);
 useEffect(()=>{if(!auth)return;const refresh=()=>{if(document.visibilityState==="visible")void load()};window.addEventListener("focus",refresh);document.addEventListener("visibilitychange",refresh);const timer=window.setInterval(refresh,30000);return()=>{window.removeEventListener("focus",refresh);document.removeEventListener("visibilitychange",refresh);window.clearInterval(timer)}},[auth]);
 function note(x:string){setToast(x);setTimeout(()=>setToast(""),2300)}
 if(!ready)return <div className="boot">正在加载 IT 账号与资产管理平台…</div>;
 if(!auth)return <Login onDone={load}/>;
 const roleName=portalRoleName(data.me),isSuper=roleName==="Administrator",canWrite=isSuper||roleName==="账号管理员"||roleName==="IT账号管理员";
 const navItems:string[]=ROLE_NAV[roleName]||ROLE_NAV["只读用户"];
 return <main className="shell"><aside><img className="logo" src="/fantuan-logo.png" alt="饭团"/><div className="product"><i>管</i><div><b>IT 账号与资产管理平台</b><small>ACCOUNT &amp; ASSET MANAGEMENT</small></div></div><nav>{navItems.map((n:string)=><button onClick={()=>{setSelected(null);setTab(n)}} className={tab===n?"on":""} key={n}><span>{NAV_ICONS[n]||"•"}</span>{n}</button>)}</nav><button className="logout" onClick={()=>{session.clear();setAuth(false)}}>退出登录</button><div className="profile"><i>{(data.me?.first_name||"IT").slice(0,1)}</i><div><b>{data.me?.first_name||data.me?.email}</b><small>{roleName}</small></div></div></aside><section className="work"><header><div><small>企业账号、人员与设备资产统一管理</small><h1>{tab}</h1></div><div><span className="date-label">统计日期：{new Date().toLocaleDateString("zh-CN")}</span>{tab==="用户与权限"&&isSuper?<button className="add" onClick={()=>setModal("user")}>＋ 开通用户</button>:canWrite&&tab==="员工管理"?<button className="add" onClick={()=>setModal("employee")}>＋ 新增员工</button>:canWrite&&tab==="部门管理"?<button className="add" onClick={()=>setModal("department")}>＋ 新增部门</button>:canWrite&&tab==="系统管理"?<button className="add" onClick={()=>setModal("system")}>＋ 新增系统</button>:canWrite&&tab==="账号台账"?<button className="add" onClick={()=>setModal("account")}>＋ 新增账号</button>:null}</div></header>
 {tab==="治理工作台"?<GovernanceWorkspace data={data} go={(next:string)=>setTab(NAV.includes(next)?next:"账号台账")}/>:tab==="账号台账"?<AccountPage rows={data.accounts} onOpen={setSelected}/>:tab==="系统管理"?<SystemPage rows={data.systems} accounts={data.accounts} onOpen={setSelected}/>:tab==="设备资产"?<DeviceOps state={data.governance} canWrite={canWrite} refresh={load} note={note}/>:tab==="员工管理"?<EmployeePage rows={data.employees} onOpen={canWrite?setSelected:()=>note("当前角色为只读权限")}/>:tab==="部门管理"?<DepartmentPage rows={data.departments} employees={data.employees} onOpen={canWrite?setSelected:()=>note("当前角色为只读权限")}/>:tab==="用户与权限"?<AccessPage rows={data.users} me={data.me} roles={data.roles} refresh={load} note={note}/>:tab==="同步中心"?<ConnectorOps state={data.governance} canWrite={canWrite} refresh={load} note={note}/>:<PermissionPage roleName={roleName}/>} 
 </section>
 {selected&&(tab==="员工管理"?<EmployeeDetail item={selected} departments={data.departments} accounts={data.accounts} isSuper={isSuper} close={()=>setSelected(null)} refresh={load} note={note}/>:tab==="部门管理"?<DepartmentDetail item={selected} employees={data.employees} isSuper={isSuper} close={()=>setSelected(null)} refresh={load} note={note}/>:tab==="系统管理"?<SystemDetail item={selected} accounts={data.accounts} canWrite={canWrite} isSuper={isSuper} close={()=>setSelected(null)} refresh={load} note={note}/>:tab==="许可证管理"?<LicenseDetail item={selected} systems={data.systems} canWrite={canWrite} isSuper={isSuper} close={()=>setSelected(null)} refresh={load} note={note}/>:<Detail item={selected} type="account" employees={data.employees} systems={data.systems} reviews={data.reviews} canWrite={canWrite} isSuper={isSuper} close={()=>setSelected(null)} refresh={load} note={note}/>)}
 {modal==="account"&&<AccountForm employees={data.employees} systems={data.systems} close={()=>setModal("")} manageSystems={()=>{setModal("");setTab("系统管理")}} done={async()=>{setModal("");await load();note("账号已创建")}}/>}
 {modal==="employee"&&<EmployeeForm departments={data.departments} close={()=>setModal("")} done={async()=>{setModal("");await load();note("员工已创建")}}/>}
 {modal==="department"&&<DepartmentForm close={()=>setModal("")} done={async()=>{setModal("");await load();note("部门已创建")}}/>}
 {modal==="system"&&<SystemForm close={()=>setModal("")} done={async()=>{setModal("");await load();note("系统已创建，可在新增账号时直接选择")}}/>}{modal==="user"&&<UserForm roles={data.roles} close={()=>setModal("")} done={async()=>{setModal("");await load();note("平台用户已创建")}}/>}{modal==="license"&&<LicenseForm systems={data.systems} close={()=>setModal("")} done={async()=>{setModal("");await load();note("许可证已创建")}}/>}
 {toast&&<div className="toast">✓ {toast}</div>}</main>
}
function Login({onDone}:{onDone:()=>void}){const[e,setE]=useState(""),[p,setP]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false);async function submit(x:any){x.preventDefault();setBusy(true);try{await login(e,p);onDone()}catch(z:any){setErr(z.message)}finally{setBusy(false)}}return <div className="loginpage"><section><img src="/fantuan-logo.png"/><h1>饭团 IT 账号与资产管理平台</h1><p>企业内部人员、平台账号与设备资产统一管理</p><form onSubmit={submit}><label>用户名<input type="text" value={e} onChange={x=>setE(x.target.value)} required/></label><label>密码<input type="password" value={p} onChange={x=>setP(x.target.value)} required/></label>{err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在登录…":"登录"}</button></form><small>ACCOUNT &amp; ASSET MANAGEMENT</small></section></div>}
function displayUserName(u:any){const first=(u.first_name||"").trim(),last=(u.last_name||"").trim(),surnames="赵钱孙李周吴郑王冯陈褚卫蒋沈韩杨朱秦许何吕施张孔曹严华金魏陶姜谢邹喻柏水窦章云苏潘葛范彭郎鲁韦昌马苗凤花方俞任袁柳鲍史唐费廉岑薛雷贺倪汤滕殷罗毕郝安常乐于时傅皮卞齐康伍余元顾孟平黄和穆萧尹姚邵汪祁毛禹狄米贝明臧计伏成戴宋茅庞熊纪舒屈项祝董梁杜阮蓝闵席季麻强贾路娄危江童颜郭梅盛林钟徐邱骆高夏蔡田樊胡凌霍虞万柯卢莫房裘缪解应宗丁宣邓郁单杭洪包诸左石崔吉龚程嵇邢裴陆荣翁荀羊甄家封芮储靳汲邴糜松井段富巫乌焦巴弓牧隗山谷车侯宓蓬全班仰秋仲伊宫宁仇栾甘厉戎祖武符刘景詹束龙叶幸司韶黎乔苍双闻莘党翟谭贡劳姬申扶堵冉宰郦雍桑桂濮牛寿通边燕冀浦尚农温别庄晏柴瞿阎充慕连习艾鱼容向古易慎戈廖庾终暨居衡步都耿满弘匡国文寇广禄阙东欧殳沃利蔚越夔隆师巩厍聂晁勾敖融冷訾辛阚那简饶空曾毋沙乜养鞠须丰巢关蒯相查后荆红游竺权逯盖益桓公";const firstLooks=surnames.includes(first.slice(0,1)),lastLooks=surnames.includes(last.slice(0,1));if(last&&lastLooks&&!firstLooks)return last+first;return first+last||u.email||"未设置姓名"}
function validEmail(v:string){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())}
function accountStatusLabel(v:string){return ({active:"有效",disabled:"已停用",locked:"已锁定",unknown:"状态未知"} as any)[v]||v}
function riskLevelLabel(v:string){return ({low:"低风险",medium:"中风险",high:"高风险",critical:"关键系统"} as any)[v]||"未评级"}
function systemTypeLabel(v:string){return ({saas:"第三方 SaaS",internal:"内部系统",software:"本地软件"} as any)[v]||v}
function risksOf(a:any){if(a.account_status==="disabled"||a.status==="archived")return[];const result:string[]=[];const notes=String(a.notes||"");const governedNonPersonal=/账号类型：(共享账号|服务账号|外部账号)/.test(notes)&&String(a.responsible_owner||"").trim();if(!a.employee&&!governedNonPersonal)result.push("无人认领");if(a.employee?.employment_status==="departed"&&a.account_status==="active")result.push("离职未停用");if(a.is_privileged)result.push("高权限");if(a.account_status==="unknown")result.push("状态未知");if(a.account_status==="locked")result.push("账号锁定");const last=a.last_login_at?new Date(a.last_login_at).getTime():0;if(a.account_status==="active"&&(!last||Date.now()-last>90*86400000))result.push(last?"90天未登录":"无登录记录");const due=a.next_review_date?new Date(String(a.next_review_date).slice(0,10)+"T23:59:59").getTime():0;if(due&&due<Date.now())result.push("核查逾期");return result}function riskOf(a:any){return risksOf(a)[0]||"正常"}
function Dashboard({data,go}:{data:any;go:(x:string)=>void}){
 const active=data.accounts.filter((a:any)=>a.account_status==="active").length;
 const riskAccounts=data.accounts.filter((a:any)=>risksOf(a).length>0);
 const riskIssues=riskAccounts.reduce((sum:number,a:any)=>sum+risksOf(a).length,0);
 const completed=data.reviews.filter((r:any)=>r.action_status==="done"||r.action_status==="none").length;
 const rate=data.reviews.length?Math.round(completed/data.reviews.length*100):100;
 return <div className="content">
  <section className="hero"><div><span>账号治理概览</span><h2>当前有 {riskAccounts.length} 个风险账号、{riskIssues} 项风险需要关注</h2><p>数据来自 Directus 实时台账，核查结论、整改状态和删除约束均保留治理记录。</p></div><button onClick={()=>go("风险中心")}>查看风险清单 →</button></section>
  <div className="metrics">{[
   ["账号总量",data.accounts.length,"覆盖 "+data.employees.length+" 名员工","teal","账号中心"],
   ["有效账号",active,"当前处于有效状态","blue","账号中心"],
   ["风险事项",riskIssues,riskAccounts.length+" 个账号需处理","red","风险中心"],
   ["核查完成率",rate+"%",data.reviews.length+" 项核查任务","amber","核查任务"]
  ].map((x:any)=><button className={"metric "+x[3]} key={x[0]} onClick={()=>go(x[4])}><span>{x[0]}</span><b>{x[1]}</b><small>● {x[2]} <i>→</i></small></button>)}</div>
  <section className="panel tablepanel"><div className="pt"><div><h3>重点风险账号</h3><p>按风险数量优先展示，点击账号进入处置</p></div><button onClick={()=>go("风险中心")}>查看全部 →</button></div><AccountTable rows={[...riskAccounts].sort((a:any,b:any)=>risksOf(b).length-risksOf(a).length).slice(0,5)} onOpen={()=>go("风险中心")}/></section>
 </div>
}
function AccessPage({rows,me,roles,refresh,note}:{rows:any[];me:any;roles:any[];refresh:()=>void;note:(x:string)=>void}){const[q,setQ]=useState("");const list=rows.filter(u=>(u.email+" "+displayUserName(u)+" "+(u.role?.name||"")).toLowerCase().includes(q.toLowerCase())).sort((a,b)=>displayUserName(a).localeCompare(displayUserName(b),"zh-CN")),activeAdmins=rows.filter(u=>u.status==="active"&&u.role?.name==="Administrator").length;return <div className="content"><section className="securitynote"><b>权限安全原则</b><span>账号管理员负责业务数据；审计及只读用户不能修改；仅超级管理员可以开通平台用户和调整角色。</span></section><div className="toolbar"><div><input placeholder="搜索姓名、邮箱或角色…" value={q} onChange={e=>setQ(e.target.value)}/></div><span>共 {list.length} 个平台用户</span></div><section className="panel tablepanel"><div className="tw"><table><thead><tr>{["用户","登录邮箱","角色","状态","最近访问","操作"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{list.map(u=><UserAccessRow key={u.id} user={u} me={me} roles={roles} activeAdmins={activeAdmins} refresh={refresh} note={note}/>)}</tbody></table></div></section></div>}
function UserAccessRow({user,me,roles,activeAdmins,refresh,note}:{user:any;me:any;roles:any[];activeAdmins:number;refresh:()=>void;note:(x:string)=>void}){const[role,setRole]=useState(user.role?.id||""),[status,setStatus]=useState(user.status||"active"),[busy,setBusy]=useState(false);const uniqueRoles=roles.filter((r,i,a)=>a.findIndex(x=>x.name===r.name)===i);async function save(){const removesLastAdmin=user.role?.name==="Administrator"&&activeAdmins<=1&&(status!=="active"||roles.find(r=>r.id===role)?.name!=="Administrator");if(user.id===me.id&&status!=="active"){note("不能停用当前登录账号");return}if(removesLastAdmin){note("必须至少保留一个启用的超级管理员");return}setBusy(true);try{await updatePortalUser(user.id,{role:role||null,status});await refresh();note("用户权限已更新，请通知该用户退出并重新登录")}catch(x:any){note(x.message)}finally{setBusy(false)}}async function remove(){if(user.id===me.id){note("不能删除当前登录账号");return}if(user.role?.name==="Administrator"&&activeAdmins<=1){note("不能删除最后一个超级管理员");return}if(!window.confirm(`确认永久删除平台用户“${user.email}”吗？删除后该用户将无法登录，此操作不可撤销。`))return;setBusy(true);try{await deletePortalUser(user.id);await refresh();note("平台用户已删除")}catch(x:any){note(x.message)}finally{setBusy(false)}}return <tr><td><i className="ud">{(user.first_name||user.email||"U")[0]}</i><b>{displayUserName(user)}</b></td><td>{user.email}</td><td><select value={role} onChange={e=>setRole(e.target.value)}>{uniqueRoles.map(r=><option value={r.id} key={r.id}>{r.name==="Administrator"?"超级管理员":r.name}</option>)}</select></td><td><select value={status} onChange={e=>setStatus(e.target.value)}><option value="active">启用</option><option value="suspended">暂停</option><option value="archived">停用</option></select></td><td>{user.last_access?.slice?.(0,10)||"从未登录"}</td><td><div className="rowactions"><button className="smallaction" disabled={busy} onClick={save}>{busy?"处理中…":"保存"}</button><button className="smalldanger" disabled={busy||user.id===me.id} onClick={remove}>删除</button></div></td></tr>}
function UserForm({roles,close,done}:{roles:any[];close:()=>void;done:()=>void}){const[f,setF]=useState<any>({status:"active"}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);const uniqueRoles=roles.filter((r,i,a)=>r.name!=="Superuser"&&a.findIndex(x=>x.name===r.name)===i);async function save(e:any){e.preventDefault();if(!f.role){setErr("请选择用户角色");return}if((f.password||"").length<10){setErr("初始密码至少 10 位");return}setBusy(true);try{await createPortalUser(f);done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}return <Modal title="开通平台用户" close={close}><form className="editform" autoComplete="off" onSubmit={save}><label>姓氏<input required value={f.last_name||""} onChange={e=>setF({...f,last_name:e.target.value})}/></label><label>名字<input required value={f.first_name||""} onChange={e=>setF({...f,first_name:e.target.value})}/></label><label>登录邮箱<input required type="email" name="new-user-email" autoComplete="off" value={f.email||""} onChange={e=>setF({...f,email:e.target.value})}/></label><label>初始密码<input required type="password" name="new-user-password" autoComplete="new-password" minLength={10} value={f.password||""} onChange={e=>setF({...f,password:e.target.value})}/></label><label>分配角色<select required value={f.role||""} onChange={e=>{setErr("");setF({...f,role:e.target.value})}}><option value="">请选择角色</option>{uniqueRoles.map(r=><option value={r.id} key={r.id}>{r.name}</option>)}</select></label><p className="formtip">日常运维请选择“IT账号管理员”，检查监督请选择“审计人员”，仅查看数据请选择“只读用户”。</p>{!uniqueRoles.length&&<span className="formerr">角色数据尚未加载，请关闭窗口后重试。</span>}{err&&<span className="formerr">{err}</span>}<button disabled={busy||!uniqueRoles.length}>{busy?"正在创建…":"创建平台用户"}</button></form></Modal>}
function DepartmentPage({rows,employees,onOpen}:{rows:any[];employees:any[];onOpen:(x:any)=>void}){return <div className="content"><section className="panel tablepanel"><div className="tw"><table><thead><tr>{["部门名称","部门负责人","员工人数","状态","操作"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map(d=><tr key={d.id} className="clickrow" onClick={()=>onOpen(d)}><td><b>{d.name}</b></td><td>{d.manager||"待设置"}</td><td>{employees.filter(e=>e.department?.id===d.id).length} 人</td><td><span className={d.status==="active"?"tag safe":"tag warn"}>{d.status==="active"?"启用":"停用"}</span></td><td><button className="dots">•••</button></td></tr>)}</tbody></table></div></section></div>}
function DepartmentForm({close,done}:{close:()=>void;done:()=>void}){const[f,setF]=useState<any>({status:"active"}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);async function save(e:any){e.preventDefault();setBusy(true);try{await createItem("departments",f);done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}return <Modal title="新增部门" close={close}><form className="editform" onSubmit={save}><label>部门名称<input required onChange={e=>setF({...f,name:e.target.value})}/></label><label>部门负责人<input onChange={e=>setF({...f,manager:e.target.value})}/></label><label>状态<select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="active">启用</option><option value="inactive">停用</option></select></label>{err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在保存…":"保存部门"}</button></form></Modal>}
function DepartmentDetail({item,employees,isSuper,close,refresh,note}:{item:any;employees:any[];isSuper:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){const[f,setF]=useState<any>({...item}),[busy,setBusy]=useState(false),linked=employees.filter(e=>e.department?.id===item.id).length;async function save(e:any){e.preventDefault();setBusy(true);try{await updateItem("departments",item.id,{name:f.name,manager:f.manager,status:f.status});await refresh();note("部门信息已保存");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}async function remove(){if(linked){note(`该部门仍有 ${linked} 名员工，请先调整员工部门`);return}if(!window.confirm(`确认删除部门“${item.name}”吗？`))return;setBusy(true);try{await deleteItem("departments",item.id);await refresh();note("部门已删除");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}return <ManageDrawer title="编辑部门" subtitle={`${linked} 名员工`} close={close}><form className="editform" onSubmit={save}><label>部门名称<input required value={f.name||""} onChange={e=>setF({...f,name:e.target.value})}/></label><label>部门负责人<input value={f.manager||""} onChange={e=>setF({...f,manager:e.target.value})}/></label><label>状态<select value={f.status||"active"} onChange={e=>setF({...f,status:e.target.value})}><option value="active">启用</option><option value="inactive">停用</option></select></label><button disabled={busy}>保存修改</button>{isSuper&&<button type="button" className="dangerbtn" disabled={busy} onClick={remove}>删除部门</button>}</form></ManageDrawer>}
function EmployeeDetail({item,departments,accounts,isSuper,close,refresh,note}:{item:any;departments:any[];accounts:any[];isSuper:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){const[f,setF]=useState<any>({...item,department:item.department?.id||"",termination_date:item.termination_date?.slice?.(0,10)||""}),[busy,setBusy]=useState(false),linked=accounts.filter(a=>a.employee?.id===item.id).length;async function save(e:any){e.preventDefault();if(!validEmail(f.email||"")){note("请输入完整有效的企业邮箱");return}setBusy(true);try{await updateItem("employees",item.id,{employee_no:f.employee_no,name:f.name,email:f.email,employment_status:f.employment_status,termination_date:f.employment_status==="departed"?(f.termination_date||new Date().toISOString().slice(0,10)):null,department:String(f.department),status:f.employment_status==="departed"?"inactive":"active"});await refresh();note("员工信息已保存");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}async function remove(){const related=accounts.filter(a=>a.employee?.id===item.id),blocking=related.filter(a=>a.account_status!=="disabled");if(blocking.length){note(`仍有 ${blocking.length} 个未停用账号，请先停用或转移`);return}const message=related.length?`该员工的 ${related.length} 个账号均已停用。删除员工后，账号记录会保留并转为“未认领”。确认继续吗？`:`确认删除员工“${item.name}”吗？此操作不可撤销。`;if(!window.confirm(message))return;setBusy(true);try{for(const account of related)await updateItem("accounts",account.id,{employee:null,responsible_owner:"待确认"});await deleteItem("employees",item.id);await refresh();note(related.length?"员工已删除，停用账号记录已保留":"员工已删除");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}return <ManageDrawer title="编辑员工" subtitle={`关联 ${linked} 个系统账号`} close={close}><form className="editform" onSubmit={save}><label>员工姓名<input required value={f.name||""} onChange={e=>setF({...f,name:e.target.value})}/></label><label>员工工号<input required value={f.employee_no||""} onChange={e=>setF({...f,employee_no:e.target.value})}/></label><label>所属部门<select required value={f.department} onChange={e=>setF({...f,department:e.target.value})}>{departments.map(d=><option value={d.id} key={d.id}>{d.name}</option>)}</select></label><label>企业邮箱<input required type="email" value={f.email||""} onChange={e=>setF({...f,email:e.target.value})}/></label><label>在职状态<select value={f.employment_status} onChange={e=>setF({...f,employment_status:e.target.value})}><option value="active">在职</option><option value="contractor">外包</option><option value="leave">休假</option><option value="departed">已离职</option></select></label>{f.employment_status==="departed"&&<label>离职日期<input required type="date" value={f.termination_date} onChange={e=>setF({...f,termination_date:e.target.value})}/></label>}<button disabled={busy}>保存修改</button>{isSuper&&<button type="button" className="dangerbtn" disabled={busy} onClick={remove}>删除员工</button>}{linked>0&&<small className="hint">存在未停用账号时不能删除；全部账号停用后可解除关联并保留账号审计记录。</small>}</form></ManageDrawer>}
function SystemDetail({item,accounts,canWrite,isSuper,close,refresh,note}:{item:any;accounts:any[];canWrite:boolean;isSuper:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){const[f,setF]=useState<any>({...item}),[busy,setBusy]=useState(false),linked=accounts.filter(a=>a.system?.id===item.id).length;async function save(e:any){e.preventDefault();setBusy(true);try{await updateItem("systems",item.id,{name:f.name,system_type:f.system_type,url:f.url,owner:f.owner,it_owner:f.it_owner,risk_level:f.risk_level,review_cycle_days:Number(f.review_cycle_days)||90,status:f.status});await refresh();note("系统信息已保存");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}async function remove(){if(linked){note(`该系统仍有 ${linked} 个账号，不能直接删除`);return}if(!window.confirm(`确认删除系统“${item.name}”吗？`))return;setBusy(true);try{await deleteItem("systems",item.id);await refresh();note("系统已删除");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}return <ManageDrawer title="编辑系统" subtitle={`关联 ${linked} 个账号`} close={close}><form className="editform" onSubmit={save}><label>系统名称<input required value={f.name||""} onChange={e=>setF({...f,name:e.target.value})}/></label><label>系统类型<select value={f.system_type||"saas"} onChange={e=>setF({...f,system_type:e.target.value})}><option value="saas">第三方 SaaS</option><option value="internal">内部系统</option><option value="software">本地软件</option></select></label><label>访问地址<input value={f.url||""} onChange={e=>setF({...f,url:e.target.value})}/></label><label>业务负责人<input value={f.owner||""} onChange={e=>setF({...f,owner:e.target.value})}/></label><label>IT 负责人<input value={f.it_owner||""} onChange={e=>setF({...f,it_owner:e.target.value})}/></label><label>风险等级<select value={f.risk_level||"medium"} onChange={e=>setF({...f,risk_level:e.target.value})}><option value="low">低</option><option value="medium">中</option><option value="high">高</option><option value="critical">关键</option></select></label><label>复核周期（天）<input disabled={!canWrite} type="number" min="1" value={f.review_cycle_days||90} onChange={e=>setF({...f,review_cycle_days:e.target.value})}/></label><label>系统状态<select disabled={!canWrite} value={f.status||"active"} onChange={e=>setF({...f,status:e.target.value})}><option value="active">启用</option><option value="inactive">停用</option></select></label>{canWrite&&<button disabled={busy}>保存修改</button>}{isSuper&&<button type="button" className="dangerbtn" disabled={busy} onClick={remove}>永久删除系统</button>}{isSuper&&linked>0&&<small className="hint">该系统关联 {linked} 个账号。请先在账号中心停用并删除或迁移这些账号，再永久删除系统。</small>}{!isSuper&&<small className="hint">系统永久删除仅限超级管理员操作；账号管理员可以编辑或停用系统。</small>}</form></ManageDrawer>}
function ManageDrawer({title,subtitle,close,children}:{title:string;subtitle:string;close:()=>void;children:any}){return <div className="drawer-layer" onClick={e=>{if(e.target===e.currentTarget)close()}}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><div><small>资料维护</small><h2>{title}</h2><p>{subtitle}</p></div><button onClick={close}>×</button></header><section>{children}</section></aside></div>}
function EmployeePage({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){const[q,setQ]=useState("");const list=useMemo(()=>rows.filter(e=>(e.name+" "+(e.employee_no||"")+" "+(e.email||"")+" "+(e.department?.name||"")).toLowerCase().includes(q.toLowerCase())),[rows,q]);return <div className="content"><div className="toolbar"><div><input placeholder="搜索姓名、工号、部门或邮箱…" value={q} onChange={e=>setQ(e.target.value)}/></div><span>共 {list.length} 名员工</span></div><section className="panel tablepanel"><div className="tw"><table><thead><tr>{["员工","工号","部门","企业邮箱","在职状态","离职日期"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{list.map(e=><tr key={e.id} className="clickrow" onClick={()=>onOpen(e)}><td><i className="ud">{(e.name||"?")[0]}</i><b>{e.name||"未命名"}</b></td><td className="mono">{e.employee_no||"—"}</td><td>{e.department?.name||"未分配"}</td><td>{e.email||"—"}</td><td><span className={e.employment_status==="active"?"tag safe":"tag warn"}>{e.employment_status==="active"?"在职":e.employment_status==="departed"?"已离职":e.employment_status==="contractor"?"外包":"休假"}</span></td><td>{e.employment_status==="departed"?(e.termination_date?.slice?.(0,10)||"待补充"):"—"}</td></tr>)}</tbody></table></div></section></div>}
function EmployeeForm({departments,close,done}:{departments:any[];close:()=>void;done:()=>void}){const[f,setF]=useState<any>({status:"active",employment_status:"active"}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);async function save(e:any){e.preventDefault();if(!validEmail(f.email||"")){setErr("请输入完整有效的企业邮箱，例如 name@fantuan.ca");return}setBusy(true);try{await createItem("employees",{...f,department:String(f.department)});done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}return <Modal title="新增员工" close={close}><form className="editform" onSubmit={save}><label>员工姓名<input required value={f.name||""} onChange={e=>setF({...f,name:e.target.value})}/></label><label>员工工号<input required value={f.employee_no||""} onChange={e=>setF({...f,employee_no:e.target.value})}/></label><label>所属部门<select required value={f.department||""} onChange={e=>setF({...f,department:e.target.value})}><option value="">请选择部门</option>{departments.map(d=><option value={d.id} key={d.id}>{d.name}</option>)}</select></label><label>企业邮箱<input required type="email" value={f.email||""} onChange={e=>setF({...f,email:e.target.value})}/></label><label>在职状态<select value={f.employment_status} onChange={e=>setF({...f,employment_status:e.target.value,status:e.target.value==="departed"?"inactive":"active"})}><option value="active">在职</option><option value="contractor">外包</option><option value="leave">休假</option><option value="departed">已离职</option></select></label>{f.employment_status==="departed"&&<label>离职日期<input required type="date" value={f.termination_date||""} onChange={e=>setF({...f,termination_date:e.target.value})}/></label>}{err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在保存…":"保存员工"}</button></form></Modal>}
function AccountPage({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){
 const[q,setQ]=useState(""),[status,setStatus]=useState("all");
 const list=useMemo(()=>rows.filter(a=>(a.username+" "+(a.employee?.name||"")+" "+(a.responsible_owner||"")+" "+(a.system?.name||"")).toLowerCase().includes(q.toLowerCase())&&(status==="all"||a.account_status===status)),[rows,q,status]);
 const people=new Set(list.map(a=>a.employee?.id?`employee:${a.employee.id}`:`owner:${a.responsible_owner||"未认领"}`)),activeKeys=new Map<string,number>();
 for(const a of rows.filter((x:any)=>x.account_status!=="disabled")){const owner=a.employee?.id?`employee:${a.employee.id}`:(a.responsible_owner?`owner:${String(a.responsible_owner).trim().toLowerCase()}`:""),system=a.system?.id||a.system?.name||a.system||"";if(owner&&system){const key=owner+"::"+system;activeKeys.set(key,(activeKeys.get(key)||0)+1)}}
 const duplicateGroups=[...activeKeys.values()].filter(n=>n>1).length;
 return <div className="content"><div className="securitynote"><b>账号唯一规则</b><span>每个人在同一个平台只能保留一个有效账号；新增、编辑和外部平台同步时都会自动校验。</span></div><div className="toolbar"><div><input placeholder="搜索员工、系统或账号…" value={q} onChange={e=>setQ(e.target.value)}/><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">全部状态</option><option value="active">有效</option><option value="disabled">停用</option><option value="unknown">未知</option></select></div><span>共 {people.size} 人，{list.length} 个平台账号 · {duplicateGroups?<strong className="formerr">{duplicateGroups} 组重复待处理</strong>:"唯一规则正常"}</span></div><section className="panel tablepanel"><GroupedAccountTable rows={list} onOpen={onOpen}/></section></div>
}
function GroupedAccountTable({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){const[expanded,setExpanded]=useState<string[]>([]);const groups=useMemo(()=>{const map=new Map<string,any>();for(const account of rows){const key=account.employee?.id?`employee:${account.employee.id}`:`owner:${account.responsible_owner||"未认领"}`;if(!map.has(key))map.set(key,{key,name:account.employee?.name||account.responsible_owner||"未认领",department:account.employee?.department?.name||"—",accounts:[]});map.get(key).accounts.push(account)}return [...map.values()]},[rows]);function toggle(key:string){setExpanded(v=>v.includes(key)?v.filter(x=>x!==key):[...v,key])}return <div className="tw grouped-accounts"><table><thead><tr>{["员工/责任人","部门","平台账号数","有效账号","涉及平台","风险账号","查看明细"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{groups.map((group:any)=>{const open=expanded.includes(group.key),systems=[...new Set(group.accounts.map((a:any)=>a.system?.name||"未关联系统"))],risky=group.accounts.filter((a:any)=>risksOf(a).length).length;return <Fragment key={group.key}><tr className="account-person" onClick={()=>toggle(group.key)}><td><i className="ud">{group.name[0]}</i><b>{group.name}</b></td><td>{group.department}</td><td><strong>{group.accounts.length}</strong> 个</td><td>{group.accounts.filter((a:any)=>a.account_status==="active").length} 个</td><td><div className="platform-list">{systems.map((x:any)=><span key={x}>{x}</span>)}</div></td><td>{risky?<span className="tag warn">{risky} 个</span>:<span className="tag safe">正常</span>}</td><td><button className="group-toggle" aria-expanded={open}>{open?"收起":"展开"} {open?"⌃":"⌄"}</button></td></tr>{open&&<tr className="account-detail-row"><td colSpan={7}><div className="account-detail-list">{group.accounts.map((a:any)=><button key={a.id} onClick={()=>onOpen(a)}><span><b>{a.system?.name||"未关联系统"}</b><small>{a.username}</small></span><span>{a.role_name||"普通权限"}</span><span className={"statuspill "+a.account_status}>{accountStatusLabel(a.account_status)}</span><span>{risksOf(a).length?risksOf(a).join("、"):"正常"}</span><em>查看/编辑 →</em></button>)}</div></td></tr>}</Fragment>})}</tbody></table>{!groups.length&&<div className="empty">暂无符合条件的账号。</div>}</div>}
function RiskPage({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){
 const count=(name:string)=>rows.filter(a=>risksOf(a).includes(name)).length;
 const issues=rows.reduce((sum,a)=>sum+risksOf(a).length,0);
 return <div className="content"><div className="riskcards">
  <article><span>风险账号</span><b>{rows.length}</b><small>合计 {issues} 项风险</small></article>
  <article><span>离职未停用</span><b>{count("离职未停用")}</b><small>建议立即停用</small></article>
  <article><span>高权限账号</span><b>{count("高权限")}</b><small>需要定期复核</small></article>
  <article><span>长期未登录</span><b>{count("90天未登录")+count("无登录记录")}</b><small>确认是否仍需保留</small></article>
 </div><section className="panel tablepanel"><AccountTable rows={rows} onOpen={onOpen}/></section></div>
}
function AccountTable({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){return <div className="tw"><table><thead><tr>{["员工/责任人","部门","系统","登录账号","角色/权限","状态","风险","最近登录",""].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map(a=>{const risks=risksOf(a);return <tr className="clickrow" key={a.id} onClick={()=>onOpen(a)}><td><i className="ud">{(a.employee?.name||a.responsible_owner||"未")[0]}</i><b>{a.employee?.name||a.responsible_owner||"未认领"}</b></td><td>{a.employee?.department?.name||"—"}</td><td>{a.system?.name||"—"}</td><td className="mono">{a.username}</td><td>{a.role_name||"—"}</td><td><span className={"statuspill "+a.account_status}>{accountStatusLabel(a.account_status)}</span></td><td><div className="risk-tags">{(risks.length?risks:["正常"]).map((risk:string)=><span key={risk} className={"tag "+(risk==="正常"?"safe":"warn")}>{risk}</span>)}</div></td><td>{a.last_login_at?String(a.last_login_at).slice(0,19).replace("T"," "):"暂未获取"}</td><td><button className="dots" aria-label={"查看账号 "+a.username}>•••</button></td></tr>})}</tbody></table></div>}
function ReviewPage({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void;refresh:()=>void;note:(x:string)=>void}){
 const columns=[
  {key:"pending",title:"待确认",filter:(r:any)=>r.result==="pending"},
  {key:"disable",title:"待停用",filter:(r:any)=>r.result==="disable"&&r.action_status!=="done"},
  {key:"reduce",title:"待降权",filter:(r:any)=>r.result==="reduce"&&r.action_status!=="done"},
  {key:"done",title:"已完成",filter:(r:any)=>r.action_status==="done"||r.action_status==="none"}
 ];
 return <div className="content kanban">{columns.map(col=>{const list=rows.filter(col.filter);return <section key={col.key}><header><b>{col.title}</b><span>{list.length}</span></header>{list.map(r=><article key={r.id} onClick={()=>onOpen(r)}><small>核查任务 # {r.id}</small><h3>{r.account?.employee?.name||r.account?.username||"账号已移除"}</h3><p>{r.account?.system?.name||"历史记录"} · {r.review_date}</p><footer><i>{(r.reviewer||"IT").slice(0,2)}</i><button>查看任务 →</button></footer></article>)}</section>})}</div>
}
function SystemPage({rows,accounts,onOpen}:{rows:any[];accounts:any[];onOpen:(x:any)=>void}){return <div className="content system-management"><div className="system-guidance"><div><h2>企业系统目录</h2><p>统一维护账号所属系统。日常下线请先停用，误建且没有关联账号时才永久删除。</p></div><span>{rows.length} 个系统</span></div><div className="systems">{rows.map((s:any)=>{const linked=accounts.filter(a=>String(a.system?.id||a.system)===String(s.id)).length;return <article key={s.id} onClick={()=>onOpen(s)} className="clickrow"><i>{s.name?.[0]||"系"}</i><div><h3>{s.name}</h3><p>{systemTypeLabel(s.system_type)} · {s.status==="inactive"?"已停用":"启用中"}</p></div><footer><span>{linked} 个关联账号</span><span>负责人：{s.it_owner||"待设置"}</span><button type="button">管理</button></footer></article>})}</div>{rows.length===0&&<div className="system-empty">尚未创建系统，请点击右上角“新增系统”。</div>}</div>}
function Detail({item,type,employees,systems,reviews,canWrite,isSuper,close,refresh,note}:{item:any;type:string;employees:any[];systems:any[];reviews:any[];canWrite:boolean;isSuper:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){const[busy,setBusy]=useState(false),[editing,setEditing]=useState(false),[form,setForm]=useState<any>({employee:item.employee?.id||"",system:item.system?.id||"",username:item.username||"",role_name:item.role_name||"",account_status:item.account_status||"active",responsible_owner:item.responsible_owner||"",is_privileged:!!item.is_privileged});async function action(kind:string){setBusy(true);try{if(type==="account"&&kind==="disable")await updateItem("accounts",item.id,{account_status:"disabled",disabled_at:new Date().toISOString().slice(0,10),status:"inactive"});if(type==="account"&&kind==="review")await createItem("account_reviews",{account:item.id,review_date:new Date().toISOString().slice(0,10),result:"pending",reviewer:"IT管理员",comment:"由账号管理门户发起",action_status:"pending"});if(type==="review"&&kind==="done")await updateItem("account_reviews",item.id,{result:"keep",action_status:"done"});await refresh();note(kind==="review"?"核查任务已创建":kind==="done"?"核查任务已完成":"账号已停用");close()}catch(e:any){note(e.message)}finally{setBusy(false)}}async function removeAccount(){if(!isSuper){note("只有超级管理员可以永久删除账号");return}if(item.account_status!=="disabled"){if(window.confirm("永久删除前必须先停用账号。是否现在停用？停用后请重新打开该账号执行永久删除。"))await action("disable");return}const related=reviews.filter(r=>r.account?.id===item.id);if(related.length){note("该账号存在 "+related.length+" 条核查历史。为保留审计证据，账号只能保持停用状态，不能永久删除。");return}if(!window.confirm("确认永久删除账号“"+item.username+"”吗？此操作不可撤销。"))return;setBusy(true);try{await deleteItem("accounts",item.id);await refresh();note("账号已永久删除");close()}catch(e:any){note(e.message)}finally{setBusy(false)}}async function save(e:any){e.preventDefault();setBusy(true);try{await updateItem("accounts",item.id,{...form,employee:form.employee||null,system:form.system||null,disabled_at:form.account_status==="disabled"?(item.disabled_at||new Date().toISOString().slice(0,10)):null,status:form.account_status==="disabled"?"inactive":"active"});await refresh();note("账号信息已保存");close()}catch(e:any){note(e.message)}finally{setBusy(false)}}return <div className="drawer-layer" onClick={e=>{if(e.target===e.currentTarget)close()}}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><div><small>{editing?"编辑账号":type==="account"?"账号详情":type==="review"?"核查任务":"系统详情"}</small><h2>{type==="account"?(item.employee?.name||"未认领"):type==="review"?(item.account?.username||"核查任务"):item.name}</h2><p>{type==="account"?item.username:type==="system"?item.url:"任务 #"+item.id}</p></div><button onClick={close}>×</button></header>{editing?<section><form className="editform" onSubmit={save}><label>所属员工<select value={form.employee} onChange={e=>setForm({...form,employee:e.target.value})}><option value="">未认领</option>{employees.map(x=><option value={x.id} key={x.id}>{x.name}（{x.employee_no||"无工号"}）</option>)}</select></label><label>所属系统<select required value={form.system} onChange={e=>setForm({...form,system:e.target.value})}><option value="">请选择系统</option>{systems.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>登录账号<input required value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>角色／权限<input value={form.role_name} onChange={e=>setForm({...form,role_name:e.target.value})}/></label><label>责任人<input value={form.responsible_owner} onChange={e=>setForm({...form,responsible_owner:e.target.value})}/></label><label>账号状态<select value={form.account_status} onChange={e=>setForm({...form,account_status:e.target.value})}><option value="active">有效</option><option value="disabled">停用</option><option value="unknown">未知</option></select></label><div className="formtip"><b>最近登录时间由系统自动识别</b><br/>{item.last_login_at?`当前记录：${String(item.last_login_at).slice(0,19).replace("T"," ")}`:"目标平台暂未提供登录记录"}；手工编辑已关闭。</div><label className="check"><input type="checkbox" checked={form.is_privileged} onChange={e=>setForm({...form,is_privileged:e.target.checked})}/> 高权限账号</label><button disabled={busy}>{busy?"正在保存…":"保存修改"}</button></form></section>:<section><h3>完整信息</h3><dl>{Object.entries(type==="account"?{"所属系统":item.system?.name||"—","角色权限":item.role_name||"—","账号状态":accountStatusLabel(item.account_status),"风险":riskOf(item),"责任人":item.responsible_owner||"待确认","最近登录":item.last_login_at?String(item.last_login_at).slice(0,19).replace("T"," "):"暂未获取","数据来源":item.login_data_source||item.source_connector||item.source||"暂未接入","最后同步":item.last_sync_at?String(item.last_sync_at).slice(0,19).replace("T"," "):"尚未同步"}:type==="system"?{"系统类型":systemTypeLabel(item.system_type),"业务负责人":item.owner||"—","IT负责人":item.it_owner||"—","风险等级":riskLevelLabel(item.risk_level),"访问地址":item.url||"—"}:{"账号":item.account?.username||"—","核查日期":item.review_date,"结论":item.result,"核查人":item.reviewer||"—","说明":item.comment||"—"}).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{String(v)}</dd></div>)}</dl></section>}<footer>{editing?<><button onClick={()=>setEditing(false)}>取消</button></>:type==="account"&&canWrite?<><button onClick={()=>setEditing(true)}>编辑账号</button><button disabled={busy} onClick={()=>action("review")}>发起核查</button><button className="danger" disabled={busy||item.account_status==="disabled"} onClick={()=>action("disable")}>{item.account_status==="disabled"?"账号已停用":"确认停用"}</button>{isSuper&&<button className="danger" disabled={busy} onClick={removeAccount}>永久删除</button>}</>:type==="review"&&canWrite?<button disabled={busy} onClick={()=>action("done")}>标记完成</button>:null}<button onClick={close}>关闭</button></footer></aside></div>}
function AccountForm({employees,systems,close,done,manageSystems}:{employees:any[];systems:any[];close:()=>void;done:()=>void;manageSystems:()=>void}){
 const[f,setF]=useState<any>({account_type:"personal",account_status:"active",status:"active",is_privileged:false,source:"manual"}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);
 async function save(e:any){
  e.preventDefault();setErr("");
  if(f.account_type==="personal"&&!f.employee){setErr("个人账号必须关联一名员工");return}
  if(f.account_type!=="personal"&&!String(f.responsible_owner||"").trim()){setErr("共享、服务或外部账号必须填写责任人");return}
  setBusy(true);
  const typeLabel=({personal:"个人账号",shared:"共享账号",service:"服务账号",external:"外部账号"} as any)[f.account_type];
  const payload={system:f.system,employee:f.employee||null,username:String(f.username||"").trim(),role_name:f.role_name||null,responsible_owner:f.responsible_owner||null,account_status:f.account_status,status:"active",is_privileged:!!f.is_privileged,source:"manual",notes:`账号类型：${typeLabel}${f.notes?`\n${f.notes}`:""}`};
  try{await createItem("accounts",payload);done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}
 }
 return <Modal title="新增账号" close={close}><form className="editform" onSubmit={save}>
  <label>账号类型<select value={f.account_type} onChange={e=>setF({...f,account_type:e.target.value,employee:e.target.value==="personal"?f.employee:""})}><option value="personal">个人账号</option><option value="shared">共享账号</option><option value="service">服务账号</option><option value="external">外部账号</option></select></label>
  <label>所属员工<select value={f.employee||""} onChange={e=>setF({...f,employee:e.target.value})}><option value="">{f.account_type==="personal"?"请选择员工":"不关联员工"}</option>{employees.map(x=><option value={x.id} key={x.id}>{x.name}（{x.employee_no||"无工号"}）</option>)}</select></label>
  <label>所属系统<div className="system-picker"><select required value={f.system||""} onChange={e=>{setErr("");setF({...f,system:e.target.value})}}><option value="">请选择系统</option>{systems.filter(x=>x.status!=="inactive").map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select><button type="button" className="system-manage-link" onClick={manageSystems}>前往系统管理</button></div><small className="field-help">新增、停用和删除系统请在“系统管理”中统一操作。</small></label>
  <label>登录账号<input required value={f.username||""} onChange={e=>setF({...f,username:e.target.value})}/></label>
  <label>角色／权限<input value={f.role_name||""} onChange={e=>setF({...f,role_name:e.target.value})}/></label>
  <label>账号责任人<input required={f.account_type!=="personal"} placeholder={f.account_type==="personal"?"可选，默认由员工本人负责":"必填，例如：IT基础设施组"} value={f.responsible_owner||""} onChange={e=>setF({...f,responsible_owner:e.target.value})}/></label>
  <label>备注<textarea value={f.notes||""} onChange={e=>setF({...f,notes:e.target.value})}/></label>
  <label className="check"><input type="checkbox" checked={!!f.is_privileged} onChange={e=>setF({...f,is_privileged:e.target.checked})}/> 高权限账号</label>
  {err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在保存…":"保存账号"}</button>
 </form></Modal>
}
function reviewResultLabel(value:string){return ({pending:"待确认",keep:"继续保留",disable:"应停用",reduce:"应降权"} as any)[value]||value}
function actionStatusLabel(value:string){return ({none:"无需处理",pending:"待处理",working:"处理中",done:"已完成"} as any)[value]||value}
function ReviewDetail({item,canWrite,close,refresh,note}:{item:any;canWrite:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){
 const[f,setF]=useState<any>({result:item.result||"pending",reviewer:item.reviewer||"",comment:item.comment||"",action_status:item.action_status||"pending",action_due_date:item.action_due_date?.slice?.(0,10)||""}),[busy,setBusy]=useState(false);
 async function save(e:any){e.preventDefault();if(f.result==="pending"&&f.action_status==="done"){note("待确认任务不能直接标记为已完成");return}setBusy(true);try{await updateItem("account_reviews",item.id,{...f,action_due_date:f.action_due_date||null,status:f.action_status==="done"?"active":"review"});await refresh();note("核查结论与整改状态已保存");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}
 return <ManageDrawer title={"核查任务 #"+item.id} subtitle={item.account?.username||"历史核查记录"} close={close}><form className="editform" onSubmit={save}><label>核查结论<select disabled={!canWrite} value={f.result} onChange={e=>setF({...f,result:e.target.value,action_status:e.target.value==="keep"?"none":"pending"})}><option value="pending">待确认</option><option value="keep">继续保留</option><option value="disable">应停用</option><option value="reduce">应降权</option></select></label><label>整改状态<select disabled={!canWrite} value={f.action_status} onChange={e=>setF({...f,action_status:e.target.value})}><option value="none">无需处理</option><option value="pending">待处理</option><option value="working">处理中</option><option value="done">已完成</option></select></label><label>整改截止日期<input disabled={!canWrite} type="date" value={f.action_due_date} onChange={e=>setF({...f,action_due_date:e.target.value})}/></label><label>核查人<input disabled={!canWrite} required value={f.reviewer} onChange={e=>setF({...f,reviewer:e.target.value})}/></label><label>核查说明<textarea disabled={!canWrite} required value={f.comment} onChange={e=>setF({...f,comment:e.target.value})}/></label><div className="formtip">当前结论：{reviewResultLabel(item.result)}；整改状态：{actionStatusLabel(item.action_status||"pending")}。历史核查记录不会随账号删除而自动清除。</div>{canWrite&&<button disabled={busy}>{busy?"正在保存…":"保存核查结论"}</button>}</form></ManageDrawer>
}
function LicensePage({rows,onOpen}:{rows:any[];onOpen:(x:any)=>void}){
 const total=rows.reduce((sum:number,x:any)=>sum+Number(x.total_seats||0),0),cost=rows.reduce((sum:number,x:any)=>sum+Number(x.annual_cost||0),0);
 return <div className="content"><div className="riskcards"><article><span>许可证项目</span><b>{rows.length}</b><small>统一管理订阅与续费</small></article><article><span>席位合计</span><b>{total}</b><small>按已登记席位统计</small></article><article><span>年度费用</span><b>{cost.toLocaleString()}</b><small>多币种金额仅作台账汇总</small></article></div><section className="panel tablepanel"><div className="tw"><table><thead><tr>{["许可证","关联系统","席位数","年度费用","续费日期","状态","操作"].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map(x=><tr key={x.id} className="clickrow" onClick={()=>onOpen(x)}><td><b>{x.name}</b></td><td>{x.system?.name||"—"}</td><td>{x.total_seats||0}</td><td>{x.currency||"CAD"} {Number(x.annual_cost||0).toLocaleString()}</td><td>{x.renewal_date?.slice?.(0,10)||"待设置"}</td><td><span className={x.status==="active"?"tag safe":"tag warn"}>{x.status==="active"?"有效":"停用"}</span></td><td><button className="dots" aria-label={"编辑许可证 "+x.name}>•••</button></td></tr>)}</tbody></table></div></section></div>
}
function LicenseForm({systems,close,done}:{systems:any[];close:()=>void;done:()=>void}){
 const[f,setF]=useState<any>({status:"active",currency:"CAD",total_seats:1,annual_cost:0}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);
 async function save(e:any){e.preventDefault();setBusy(true);try{await createItem("licenses",{...f,system:f.system||null,total_seats:Number(f.total_seats),annual_cost:Number(f.annual_cost)});done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}
 return <Modal title="新增许可证" close={close}><form className="editform" onSubmit={save}><label>许可证名称<input required value={f.name||""} onChange={e=>setF({...f,name:e.target.value})}/></label><label>关联系统<select required value={f.system||""} onChange={e=>setF({...f,system:e.target.value})}><option value="">请选择系统</option>{systems.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>席位数<input required type="number" min="0" value={f.total_seats} onChange={e=>setF({...f,total_seats:e.target.value})}/></label><label>年度费用<input required type="number" min="0" step="0.01" value={f.annual_cost} onChange={e=>setF({...f,annual_cost:e.target.value})}/></label><label>币种<select value={f.currency} onChange={e=>setF({...f,currency:e.target.value})}><option>CAD</option><option>USD</option><option>CNY</option></select></label><label>续费日期<input required type="date" value={f.renewal_date||""} onChange={e=>setF({...f,renewal_date:e.target.value})}/></label>{err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在保存…":"保存许可证"}</button></form></Modal>
}
function LicenseDetail({item,systems,canWrite,isSuper,close,refresh,note}:{item:any;systems:any[];canWrite:boolean;isSuper:boolean;close:()=>void;refresh:()=>void;note:(x:string)=>void}){
 const[f,setF]=useState<any>({name:item.name||"",system:item.system?.id||"",total_seats:item.total_seats||0,annual_cost:item.annual_cost||0,currency:item.currency||"CAD",renewal_date:item.renewal_date?.slice?.(0,10)||"",status:item.status||"active"}),[busy,setBusy]=useState(false);
 async function save(e:any){e.preventDefault();setBusy(true);try{await updateItem("licenses",item.id,{...f,system:f.system||null,total_seats:Number(f.total_seats),annual_cost:Number(f.annual_cost)});await refresh();note("许可证信息已保存");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}
 async function remove(){if(!isSuper){note("只有超级管理员可以永久删除许可证");return}if(!window.confirm("确认永久删除许可证“"+item.name+"”吗？此操作不可撤销。"))return;setBusy(true);try{await deleteItem("licenses",item.id);await refresh();note("许可证已删除");close()}catch(x:any){note(x.message)}finally{setBusy(false)}}
 return <ManageDrawer title="编辑许可证" subtitle={item.system?.name||"未关联系统"} close={close}><form className="editform" onSubmit={save}><label>许可证名称<input disabled={!canWrite} required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>关联系统<select disabled={!canWrite} required value={f.system} onChange={e=>setF({...f,system:e.target.value})}><option value="">请选择系统</option>{systems.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>席位数<input disabled={!canWrite} required type="number" min="0" value={f.total_seats} onChange={e=>setF({...f,total_seats:e.target.value})}/></label><label>年度费用<input disabled={!canWrite} required type="number" min="0" step="0.01" value={f.annual_cost} onChange={e=>setF({...f,annual_cost:e.target.value})}/></label><label>币种<select disabled={!canWrite} value={f.currency} onChange={e=>setF({...f,currency:e.target.value})}><option>CAD</option><option>USD</option><option>CNY</option></select></label><label>续费日期<input disabled={!canWrite} required type="date" value={f.renewal_date} onChange={e=>setF({...f,renewal_date:e.target.value})}/></label><label>状态<select disabled={!canWrite} value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="active">有效</option><option value="inactive">停用</option></select></label>{canWrite&&<button disabled={busy}>{busy?"正在保存…":"保存修改"}</button>}{isSuper&&<button type="button" className="dangerbtn" disabled={busy} onClick={remove}>永久删除许可证</button>}</form></ManageDrawer>
}function SystemForm({close,done}:{close:()=>void;done:()=>void}){const[f,setF]=useState<any>({status:"active",system_type:"saas",risk_level:"medium",review_cycle_days:90}),[err,setErr]=useState(""),[busy,setBusy]=useState(false);async function save(e:any){e.preventDefault();setBusy(true);try{await createItem("systems",{...f,review_cycle_days:Number(f.review_cycle_days)});done()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}return <Modal title="新增系统" close={close}><form className="editform" onSubmit={save}><label>系统名称<input required onChange={e=>setF({...f,name:e.target.value})}/></label><label>系统类型<select value={f.system_type} onChange={e=>setF({...f,system_type:e.target.value})}><option value="saas">第三方 SaaS</option><option value="internal">内部系统</option><option value="software">本地软件</option></select></label><label>访问地址<input type="url" placeholder="https://" onChange={e=>setF({...f,url:e.target.value})}/></label><label>业务负责人<input onChange={e=>setF({...f,owner:e.target.value})}/></label><label>IT 负责人<input onChange={e=>setF({...f,it_owner:e.target.value})}/></label><label>风险等级<select value={f.risk_level} onChange={e=>setF({...f,risk_level:e.target.value})}><option value="low">低风险</option><option value="medium">中风险</option><option value="high">高风险</option><option value="critical">关键系统</option></select></label><label>账号复核周期（天）<input required type="number" min="1" value={f.review_cycle_days} onChange={e=>setF({...f,review_cycle_days:e.target.value})}/></label>{err&&<span className="formerr">{err}</span>}<button disabled={busy}>{busy?"正在保存…":"保存系统"}</button></form></Modal>}
function Modal({title,close,children}:{title:string;close:()=>void;children:any}){return <div className="drawer-layer" onClick={e=>{if(e.target===e.currentTarget)close()}}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button onClick={close}>×</button></header><section>{children}</section></aside></div>}

